

// World event accessors and counters (physics_world.c).

extension World {
    /// The number of awake bodies. These are bodies that are in the awake solver set, which
    /// includes dynamic and kinematic bodies that have not gone to sleep.
    public func awakeBodyCount() -> Int32 {
        Int32(solverSets[Int(SetType.awakeSet.rawValue)].bodySims.count)
    }

    /// Body move events generated by the most recent step. The array is empty when no body moved.
    public func bodyEvents() -> [BodyMoveEvent] {
        bodyMoveEvents
    }

    /// Sensor begin/end touch events generated by the most recent step, in C's packed layout.
    public func sensorEventBuffers() -> SensorEvents {
        let begin = sensorBeginEvents
        let end = sensorEndEvents.published
        return begin.withUnsafeBufferPointer { beginPointer in
            end.withUnsafeBufferPointer { endPointer in
                SensorEvents(beginEvents: beginPointer, endEvents: endPointer)
            }
        }
    }

    /// Contact begin/end/hit events generated by the most recent step.
    public func contactEvents() -> ContactEvents {
        contactBeginEvents.withUnsafeBufferPointer { begin in
            contactEndEvents.published.withUnsafeBufferPointer { end in
                contactHitEvents.withUnsafeBufferPointer { hit in
                    ContactEvents(beginEvents: begin, endEvents: end, hitEvents: hit)
                }
            }
        }
    }

    /// The number of contacts in the world that are touching.
    public func touchingContactCount() -> Int32 {
        Int32(contacts.reduce(0) { count, contact in
            count + ((contact.flags & ContactFlags.touching.rawValue) != 0 ? 1 : 0)
        })
    }
}

extension World {
    /// Number of live bodies in the world.
    public var bodyCount: Int32 {
        bodyIdPool.idCount
    }

    /// Number of live contacts in the world.
    public var contactCount: Int32 {
        contactIdPool.idCount
    }

    /// Number of live joints in the world.
    public var jointCount: Int32 {
        jointIdPool.idCount
    }

    /// Number of hulls currently interned in the world database.
    public var hullDatabaseCount: Int {
        hullDatabase.count
    }

    /// Number of live compound shapes. The broad-phase uses this to pick between the fast and
    /// slow pair paths, so a leak here is a permanent performance regression.
    public var compoundShapeCountValue: Int32 {
        compoundShapeCount
    }

    /// True while the body id refers to a live body.
    public func bodyIsValid(_ bodyId: BodyID) -> Bool {
        let index = bodyId.index1 - 1
        guard index >= 0, Int(index) < bodies.count else { return false }
        let body = bodies[Int(index)]
        return body.id != B3.nullIndex && body.generation == bodyId.generation
    }
}

extension World {
    /// Diagnostic counters for the world, mirroring `b3World_GetCounters`.
    public func counters() -> Counters {
        var counters = Counters()
        counters.bodyCount = bodyCount
        counters.shapeCount = Int32(shapes.count)
        counters.contactCount = contactCount
        counters.jointCount = jointCount
        counters.islandCount = Int32(islands.count)
        counters.satCallCount = satCallCount
        counters.satCacheHitCount = satCacheHitCount
        counters.recycledContactCount = taskContexts[0].recycledContactCount
        counters.staticTreeHeight = broadPhase.trees[Int(BodyType.staticBody.rawValue)].height
        counters.treeHeight = broadPhase.trees[Int(BodyType.dynamicBody.rawValue)].height

        // Per-color constraint counts and the awake non-touching contact total.
        counters.awakeContactCount = 0
        for i in 0..<Int(B3.graphColorCount) {
            let color = constraintGraph.colors[i]
            let colorContactCount = color.convexContacts.count + color.contacts.count
            counters.colorCounts[i] = Int32(colorContactCount + color.jointSims.count)
            counters.awakeContactCount += Int32(colorContactCount)
        }
        counters.awakeContactCount += Int32(
            solverSets[Int(SetType.awakeSet.rawValue)].contactIndices.count
        )

        return counters
    }
}

extension World {
    /// Resolve the user material id at a hit point. Mesh and height-field shapes use the manifold
    /// point's triangle index; compound shapes resolve through the participating child.
    func shapeUserMaterialId(_ shape: Shape, _ childIndex: Int32, _ triangleIndex: Int32) -> UInt64 {
        if shape.materialCount == 0 {
            return 0
        }

        var materialIndex: Int32 = 0

        switch shape.geometry {
        case .mesh(let mesh):
            if let data = mesh.data {
                materialIndex = Int32(data.materialIndices[Int(triangleIndex)])
            }

        case .heightField(let field):
            materialIndex = field.material(triangle: triangleIndex)

        case .compound(let compound):
            let child = compound.child(at: Int(childIndex))
            if case .mesh(let mesh) = child.geometry, let data = mesh.data {
                let meshMaterialIndex = Int32(data.materialIndices[Int(triangleIndex)])
                b3Assert(meshMaterialIndex >= 0 && meshMaterialIndex < Int32(child.materialIndices.count))
                materialIndex = Int32(child.materialIndices[Int(meshMaterialIndex)])
            } else {
                materialIndex = Int32(child.materialIndices[0])
            }

        default:
            break
        }

        materialIndex = clampInt(materialIndex, 0, shape.materialCount - 1)
        return shape.material(materialIndex).userMaterialId
    }

    /// Emit contact hit events for the step. Ported from the hit-event block in solver.c.
    func emitContactHitEvents() {
        let threshold = hitEventThreshold

        // Iterate contacts in id order so events are deterministic.
        for contactId in 0..<Int32(contacts.count) {
            // Filter on the cheap scalar fields before copying the contact: the copy retains three
            // arrays, and almost every slot fails this test.
            let flags = contacts[Int(contactId)].flags
            guard (flags & ContactFlags.simEnableHitEvent.rawValue) != 0 else {
                continue
            }
            let contact = contacts[Int(contactId)]
            guard contact.contactId != B3.nullIndex,
                contact.setIndex == SetType.awakeSet.rawValue,
                contact.colorIndex != B3.nullIndex
            else {
                continue
            }

            let shapeA = shapes[Int(contact.shapeIdA)]
            let shapeB = shapes[Int(contact.shapeIdB)]
            let simA = jointBodySim(shapeA.bodyId)
            let simB = jointBodySim(shapeB.bodyId)
            let midCenter = lerpPosition(simA.center, simB.center, 0.5)

            var event = ContactHitEvent()
            event.approachSpeed = threshold

            var found = false
            var triangleIndex: Int32 = 0

            for manifoldIndex in 0..<Int(contact.manifoldCount) {
                let manifold = contact.manifolds[manifoldIndex]
                for pointIndex in 0..<Int(manifold.pointCount) {
                    let mp = manifold.points[pointIndex]
                    let approachSpeed = -mp.normalVelocity

                    // Check the total impulse because the point may be speculative and not colliding.
                    if approachSpeed > event.approachSpeed && mp.totalNormalImpulse > 0 {
                        event.approachSpeed = approachSpeed
                        event.point = offsetPos(midCenter, lerp(mp.anchorA, mp.anchorB, 0.5))
                        event.normal = manifold.normal
                        triangleIndex = mp.triangleIndex
                        found = true
                    }
                }
            }

            guard found else {
                continue
            }

            event.shapeIdA = ShapeID(
                index1: shapeA.id + 1, world0: worldId, generation: shapeA.generation
            )
            event.shapeIdB = ShapeID(
                index1: shapeB.id + 1, world0: worldId, generation: shapeB.generation
            )
            event.contactId = ContactID(
                index1: contact.contactId + 1, world0: worldId, generation: contact.generation
            )

            // shapeB is never a compound today, so the child index is irrelevant for it.
            event.userMaterialIdA = shapeUserMaterialId(shapeA, contact.childIndex, triangleIndex)
            event.userMaterialIdB = shapeUserMaterialId(shapeB, 0, triangleIndex)

            contactHitEvents.append(event)
        }
    }
}

// MARK: - World tuning

extension World {
    /// Set the contact softness and the maximum push-out speed in one call, matching C's
    /// `b3World_SetContactTuning`.
    public func setContactTuning(hertz: Float, dampingRatio: Float, contactSpeed: Float) {
        self.contactHertz = hertz
        self.contactDampingRatio = dampingRatio
        self.contactSpeed = clampFloat(contactSpeed, 0, .greatestFiniteMagnitude)
    }

    /// Number of bodies in the awake solver set.
    public func awakeBodyCountPublic() -> Int32 {
        awakeBodyCount()
    }

    /// Profiling data for the most recent step.
    public func profileData() -> Profile {
        profile
    }

    /// True while sleeping is enabled for the world.
    public func isSleepingEnabled() -> Bool {
        enableSleep
    }

    /// True while warm starting is enabled.
    public func isWarmStartingEnabled() -> Bool {
        enableWarmStarting
    }

    /// True while continuous collision is enabled.
    public func isContinuousEnabled() -> Bool {
        enableContinuous
    }

    /// Enable or disable sleeping for the whole world.
    public func enableSleeping(_ enable: Bool) {
        enableSleep = enable
    }

    /// Enable or disable warm starting.
    public func enableWarmStarting(_ enable: Bool) {
        enableWarmStarting = enable
    }

    /// Enable or disable continuous collision.
    public func enableContinuous(_ enable: Bool) {
        enableContinuous = enable
    }
}
